static inline const RoMobInfo* ro_mob_info(int id) {
    int lo = 0, hi = 1004 - 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        if (RO_MOBS[mid].id == id) return &RO_MOBS[mid];
        if (RO_MOBS[mid].id < id) lo = mid + 1; else hi = mid - 1;
    }
    return 0;
}
